using System.Threading.Tasks;
using Xunit;

namespace Vibranium.Tests;

// N111 (self-fix-y4). Every variable that an earlier part of an expression declares is on vib-self's binding stack while
// a later part of the same expression is typed (C#'s scope). In scope is not assigned: reading it where it is not
// definitely assigned stays an error (VIB001).
public sealed class Round12SelfEarlierDeclarationTests
{
    // A variable declared in an earlier part of an expression (inside a cast, a constructor or intrinsic argument, an
    // index, the right side of an assignment, a receiver) is the one a later part of the same expression names, even
    // when a field, constant, primary-constructor parameter, or a local or parameter of the enclosing function has the
    // same name. Binding the other one picks the other overload. The expected text is the .NET output.
    [Theory]
    [InlineData("n111-and-cond-none", "bool c = false;\nWriteLine((GetB(out int y) && y > 0 ? H.Sum(0, (c ? 1 : y)) : -5));\nstatic bool GetB(out int v) { v = 3; return true; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
    [InlineData("n111-and-plain-none", "WriteLine((GetB(out int y) && y > 0 ? H.Sum(0, y) : -5));\nstatic bool GetB(out int v) { v = 3; return true; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
    [InlineData("n111-arg-cond-none", "bool c = false;\nWriteLine(H.Sum(GetS(out int y), (c ? 1 : y)));\nstatic int GetS(out int v) { v = 3; return 0; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
    [InlineData("n111-arg-plain-none", "WriteLine(H.Sum(GetS(out int y), y));\nstatic int GetS(out int v) { v = 3; return 0; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
    [InlineData("n111-arms-cond-none", "bool c = false; bool b = true;\nWriteLine((b ? GetS(out int y) : (y = 3)) + H.Sum(0, (c ? 1 : y)));\nstatic int GetS(out int v) { v = 3; return 0; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
    [InlineData("n111-arms-plain-none", "bool b = true;\nWriteLine((b ? GetS(out int y) : (y = 3)) + H.Sum(0, y));\nstatic int GetS(out int v) { v = 3; return 0; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
