    // An `out T name` argument is in scope for the rest of the argument list. Passing it again by `out` there is valid
    // C# and an overlapping borrow in Vibranium: every frontend reports VIB002 and nothing else. (Typed without the
    // variable, the second argument made vib-self report VIB000 as well, or VIB000 alone.)
    [Theory]
    [InlineData("n111-genout-plain-const", "WriteLine(T.Run(false));\nstatic class T { public const double y = 0.5;  public static long Run(bool c) { return G3.Pass(out int y, out y, 3); } }\nstatic class G3 { public static long Pass<T>(out int a, out T b, T v) { a = 1; b = v; return 7; } }\n")]
    [InlineData("n111-genout-plain-ifield", "WriteLine(new T().Run(false));\nsealed class T { public double y = 0.5;  public long Run(bool c) { return G3.Pass(out int y, out y, 3); } }\nstatic class G3 { public static long Pass<T>(out int a, out T b, T v) { a = 1; b = v; return 7; } }\n")]
    [InlineData("n111-genout-plain-lconst", "const double y = 0.5;\nWriteLine(L(false) + (long)(y * 0));\nstatic long L(bool c) { return G3.Pass(out int y, out y, 3); }\nstatic class G3 { public static long Pass<T>(out int a, out T b, T v) { a = 1; b = v; return 7; } }\n")]
    [InlineData("n111-genout-plain-none", "WriteLine(G3.Pass(out int y, out y, 3));\nstatic class G3 { public static long Pass<T>(out int a, out T b, T v) { a = 1; b = v; return 7; } }\n")]
    [InlineData("n111-genout-plain-param", "WriteLine(Outer(false, 0.5));\nstatic long Outer(bool c0, double y) { return L(c0) + (long)(y * 0); static long L(bool c) { return G3.Pass(out int y, out y, 3); } }\nstatic class G3 { public static long Pass<T>(out int a, out T b, T v) { a = 1; b = v; return 7; } }\n")]
