    // The same scopes, negative: the earlier part declares the variable on one path only and the later part reads,
    // passes, moves or returns it (CS0165), or an earlier `out` argument declares it and a later argument of the same
    // list reads it. vib-self must report exactly VIB001.
    [Theory]
    [InlineData("NEG-cast-and-read", "WriteLine(Run(false, false, 1));\nstatic long Run(bool b, bool c, int k)\n{\n    return H.Sum((long)(b && GetB(out int y) ? 1 : 0), y);\n}\nstatic bool GetB(out int v) { v = 3; return true; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n")]
    [InlineData("NEG-cast-arm-ref", "WriteLine(Run(false, false, 1));\nstatic long Run(bool b, bool c, int k)\n{\n    return H.Sum((long)(b ? GetS(out int y) : 0), Bump(ref y));\n}\nstatic int GetS(out int v) { v = 3; return 0; }\nstatic int Bump(ref int v) { v += 1; return v; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n")]
    [InlineData("NEG-cast-pat-partial", "WriteLine(Run(false, false, 1));\nstatic long Run(bool b, bool c, int k)\n{\n    return H.Sum((long)(PickN() is Some<int>(var y) ? 1 : 0), (c ? (y = 1) : 0) + y);\n}\nstatic Option<int> PickN() { return None; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n")]
    [InlineData("NEG-cast-and-moveintr", "WriteLine(Run(false, false, 1));\nstatic long Run(bool b, bool c, int k)\n{\n    return H.Sum((long)(b && GetBB(out Box x) ? 1 : 0), Take(Move(x)));\n}\nstatic bool GetBB(out Box v) { v = new Box(1); return true; }\nstatic int Take(Box b) => b.V;\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\nsealed class Box(int v) { public int V = v; public int Get() => V; }\n")]
    [InlineData("NEG-cast-arm-call", "WriteLine(Run(false, false, 1));\nstatic long Run(bool b, bool c, int k)\n{\n    return H.Sum((long)(b ? GetSB(out Box x) : 0), x.Get());\n}\nstatic int GetSB(out Box v) { v = new Box(1); return 0; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\nsealed class Box(int v) { public int V = v; public int Get() => V; }\n")]
