    [InlineData("NEG-new-arm-arith", "WriteLine(Run(false, false, 1));\nstatic long Run(bool b, bool c, int k)\n{\n    return H.Sum(new P2((b ? GetS(out int y) : 0), 1.0).A, y + 1);\n}\nstatic int GetS(out int v) { v = 3; return 0; }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\nsealed class P2(int a, double b) { public int A = a; public long V = (long)b; }\n")]
