// self-fix-y4: more rows of Round12SelfEarlierDeclarationTests (xUnit runs one class's rows serially).
public sealed class Round12SelfEarlierDeclarationShadowTests
{
    // A variable declared in an earlier part of an expression (inside a cast, a constructor or intrinsic argument, an
    // index, the right side of an assignment, a receiver) is the one a later part of the same expression names, even
    // when a field, constant, primary-constructor parameter, or a local or parameter of the enclosing function has the
    // same name. Binding the other one picks the other overload. The expected text is the .NET output.
    [Theory]
    [InlineData("n111-and-cond-const", "WriteLine(T.Run(false));\nstatic class T { public const double y = 0.5; static bool GetB(out int v) { v = 3; return true; } public static long Run(bool c) { return (GetB(out int y) && y > 0 ? H.Sum(0, (c ? 1 : y)) : -5); } }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
    [InlineData("n111-and-plain-const", "WriteLine(T.Run(false));\nstatic class T { public const double y = 0.5; static bool GetB(out int v) { v = 3; return true; } public static long Run(bool c) { return (GetB(out int y) && y > 0 ? H.Sum(0, y) : -5); } }\nstatic class H { public static long Sum(long a, long x) => a + x; public static long Sum(long a, double x) => -1; }\n", "3\n")]
